DROP TABLE IF EXISTS `room_bookings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `room_bookings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `room_name` varchar(255) NOT NULL COMMENT 'ชื่อห้องประชุม',
  `booker_name` varchar(255) NOT NULL COMMENT 'ชื่อผู้จอง',
  `start_time` datetime NOT NULL COMMENT 'วัน-เวลาเริ่มจอง',
  `end_time` datetime NOT NULL COMMENT 'วัน-เวลาสิ้นสุด',
  `purpose` text DEFAULT NULL COMMENT 'วัตถุประสงค์การจอง/เรื่อง',
  `status` varchar(50) DEFAULT 'จองสำเร็จ' COMMENT 'สถานะการจอง',
  PRIMARY KEY (`id`),
  KEY `idx_booker_name` (`booker_name`),
  KEY `idx_room_name` (`room_name`),
  KEY `idx_start_time` (`start_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3456 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
